"""Manual self-check for autogenerated analysis-config panel hashes.

Verifies byte-for-byte integrity of panel YAMLs against the hashes recorded in
tools/config_management/.config_hashes.json. Fails on missing files, changed
content, or a stale hash DB.

Not part of the automatic CI/pytest suite. Automated enforcement is provided by
the pre-commit "hash-check" hook (tools/config_management/hash_checker.py). Run
manually from the project root:

    python3 tools/test_autogen_config_manual.py
"""

import hashlib
import json
import sys
from pathlib import Path

_TOOLS_DIR = Path(__file__).resolve().parent
_PROJECT_ROOT = _TOOLS_DIR.parent
_SRC = _PROJECT_ROOT / "src"

HASH_DB = _TOOLS_DIR / "config_management" / ".config_hashes.json"
ANALYSIS_CONFIGS = _SRC / "rocprof_compute_soc" / "analysis_configs"


def md5(path: Path) -> str:
    return hashlib.md5(path.read_bytes()).hexdigest()


def check_config_hashes_match_files() -> None:
    assert HASH_DB.exists(), f"Missing hash DB: {HASH_DB}"
    assert ANALYSIS_CONFIGS.exists(), (
        f"Missing analysis configs dir: {ANALYSIS_CONFIGS}"
    )

    with HASH_DB.open() as f:
        data = json.load(f)

    assert "archs" in data, "Hash DB missing 'archs' key"
    assert isinstance(data["archs"], dict)

    failures: list[str] = []

    for arch, arch_data in data["archs"].items():
        arch_dir = ANALYSIS_CONFIGS / arch
        if not arch_dir.exists():
            failures.append(f"Arch directory missing: {arch_dir}")
            continue

        files = arch_data.get("files", {})
        if not isinstance(files, dict):
            failures.append(f"'files' for {arch} is not a dict")
            continue

        for rel_path, expected_hash in files.items():
            panel_path = arch_dir / rel_path
            if not panel_path.exists():
                failures.append(f"Missing panel file: {panel_path}")
                continue

            actual_hash = md5(panel_path)
            if actual_hash != expected_hash:
                failures.append(
                    f"[{arch}] Panel hash mismatch: {panel_path}\n"
                    f"  expected: {expected_hash}\n"
                    f"  actual:   {actual_hash}"
                )

    assert not failures, (
        "Hash consistency failures:\n\n" + "\n".join(failures)
    )


def main() -> None:
    check_config_hashes_match_files()
    print("Autogen config hash consistency check passed.")


if __name__ == "__main__":
    try:
        main()
    except AssertionError as err:
        print(f"FAILED: {err}", file=sys.stderr)
        sys.exit(1)
